import{_ as i,l as s,o as e,c as l,v as t,p as d,x as r,d as E,i as n,S as c}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"TAGE","description":"","frontmatter":{"title":"TAGE","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/tage-predictor.md","filePath":"cs/tage-predictor.md","lastUpdated":1789023840000}'),h={name:"cs/tage-predictor.md"};function p(T,a,A,_,B,m){const o=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="tage" tabindex="-1">TAGE <a class="header-anchor" href="#tage" aria-label="Permalink to &quot;TAGE&quot;">​</a></h1><div class="epigraph"><p>用一组几何增长的历史长度，每张表带部分标签：最长且命中的那张说话，短历史只在长的缺席时顶上。</p><footer>—— 据 Seznec and Michaud, A case for (partially) tagged geometric history length predictors, JILP 2006 整理</footer></div><p><a href="/cs/gshare-predictor">上一课</a>用一条 GHR 异或 PC 索引一张 PHT。固定长度：短了看不见远相关，长了新分支训不熟、别名把旧相关挤掉。本课不重做异或散列。缺口是：<strong>同一时刻让短历史与长历史共存，用标签决定哪一张表真的「认出」了这条分支。</strong> 这就是 TAGE（TAgged GEometric）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>有的分支只依赖最近 1–2 次方向，有的依赖几十次以前的一次比较（循环嵌套、解释器分发）。gshare 只能选一个 \\(h\\)。把 \\(h\\) 拉长，PHT 里大量槽永远训不热。把多张不同 \\(h\\) 的表简单并排，又会在同一 PC 上互相打架。缺口不是再加锦标赛的一路局部，而是<strong>按几何序列准备若干张带标签的表，命中最长者优先</strong>。</p><p><span class="marginnote">几何：例如 0、2、4、8、16、32、64。基础表（T0）通常无标签，相当于 bimodal，保证总有一个预测。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>T0：按 PC 索引的两位计数器，无标签。\\(T_i\\)（\\(i\\ge 1\\)）：用 <code>hash(PC, GHR[h_i])</code> 索引，条目含部分标签、有符号计数器、有用位。预测：从最长 \\(i\\) 往下找第一条标签匹配；若全未命中，用 T0。更新：只更新提供者（以及偶尔分配更高表项）；有用位在正确预测时置位，周期性衰减，以保护仍有价值的长历史项。</p>',8)),(e(),d(c,null,{default:r(()=>[n(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20T0%5B%22T0%20%E6%97%A0%E6%A0%87%E7%AD%BE%E5%9F%BA%E7%BA%BF%22%5D%20--%3E%20ALT%5B%22%E6%97%A0%E6%9B%B4%E9%95%BF%E5%91%BD%E4%B8%AD%E5%88%99%E7%94%A8%20T0%22%5D%0A%20%20T1%5B%22T1%20%E7%9F%AD%E5%8E%86%E5%8F%B2%2B%E6%A0%87%E7%AD%BE%22%5D%20--%3E%20HIT%5B%22%E6%9C%80%E9%95%BF%E5%91%BD%E4%B8%AD%E8%80%85%E6%8F%90%E4%BE%9B%E6%96%B9%E5%90%91%22%5D%0A%20%20TN%5B%22Tn%20%E9%95%BF%E5%8E%86%E5%8F%B2%2B%E6%A0%87%E7%AD%BE%22%5D%20--%3E%20HIT%0A%20%20HIT%20--%3E%20PRED%5B%22%E9%A2%84%E6%B5%8B%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>分配发生在误预测且更高表有可替换项时：新项写入当时的长历史散列与标签。这与 cache 填入相似，只是「命中」是标签相等。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>TAGE 把 gshare 的「一张表、一种 \\(h\\)」拆成可共存的多种 \\(h\\)。别名被部分标签挡住：错误的历史不会悄悄改到别人的计数器。有用位是替换策略，不是 ISA。对乱序核，核对仍在提交端；推测更新可用检查点回滚 GHR 与新分配，原则与上一课相同，结构更重。</p><p>实用变体（TAGE-SC-L 等）再加统计校正与循环预测器，那是后课循环预测要接的插件，本课只钉几何表与提供规则。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把感知器的点积引入 TAGE 表内。间接跳转的 ITTAGE 是同一思想换「目标」而不是方向，下一课之后才碰。也不比较商业 CPU 的具体表项数。</p><p>后课默认：需要超长相关就想到带标签的几何历史；gshare 仍是最短实现。线性可分的分支用权重，是下一课感知器。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>TAGE：几何长度 + 部分标签，最长命中者预测。</li><li>基线无标签表保证冷分支仍有答案。</li><li>感知器走另一条：把历史当特征而不是索引。</li><li>出处：Seznec and Michaud, <em>JILP</em>, 2006；Seznec 后续 TAGE 变体。</li></ul>',9))])}const P=i(h,[["render",p]]);export{u as __pageData,P as default};
